mapper.select:

SELECT 
FROM stl_statement s
JOIN bas_company c ON c.id = s.company_id
JOIN sup_supplier p ON p.id = s.partner_id
WHERE true
AND s.create_by = #{scope.userId}

AND p.product_lines <@ #{scope.lines.values, typeHandler=com.lingmao.scm.common.mybatis.StringArrayTypeHandler}::varchar[]

    AND s.status IN #{st}

AND s.company_id = #{q.companyId}
AND s.partner_id = #{q.partnerId}
AND s.period_end >= #{q.periodFrom}
AND s.period_start <= #{q.periodTo}

    AND (s.no ILIKE #{kw} OR p.code ILIKE #{kw} OR p.name LIKE #{kw} OR p.short_name LIKE #{kw})

ORDER BY s.id DESC
